void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    if (!pdf || !obj) {
        return;
    }

    if (obj->size <= 0) {
        return;
    }

    size_t dict_start = obj->data_start;
    size_t dict_end = obj->data_end;

    if (dict_start >= dict_end) {
        return;
    }

    // Assume the PDF object has a dictionary with key-value pairs
    for (size_t i = dict_start; i < dict_end; ++i) {
        char key[obj->key_size + 1];
        memset(key, 0, obj->key_size + 1);

        memcpy(key, obj->data + i, obj->key_size);

        if (strcmp(key, "Linearized") == 0) {
            // Handle linearized PDF case
            obj->flags |= PDF_OBJ_LINEARIZED;
        } else if (strcmp(key, "Launch") == 0) {
            // Handle launch action
            obj->flags |= PDF_OBJ_HAS_LAUNCH;
        } else if (strcmp(key, "JS") == 0) {
            // Handle JavaScript reference
            obj->flags |= PDF_OBJ_HAS_JS;
        } else if (strcmp(key, "Filter") == 0) {
            // Handle filter
            obj->flags |= PDF_OBJ_HAS_FILTER;
        }

        i += obj->key_size;
    }

    // Debug message
    fprintf(stderr, "Parsed object %zu with flags: 0x%x\n", obj->id, obj->flags);
}

void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    // Initialize necessary variables
    size_t obj_size = 0;
    const char *dict_start = nullptr;
    const char *dict_end = nullptr;

    // Check the size of the object
    obj_size = get_object_size(pdf, obj);
    if (obj_size == 0) {
        log_debug("Object size is zero; nothing to parse.");
        return;
    }

    // Locate the start and end of the object's dictionary
    dict_start = find_dict_start(pdf, obj);
    dict_end = find_dict_end(pdf, obj);

    if (!dict_start || !dict_end) {
        log_debug("Failed to locate dictionary boundaries.");
        return;
    }

    // Process PDF names within the dictionary
    const char *current = dict_start;
    while (current < dict_end) {
        const char *name = parse_pdf_name(pdf, current);
        if (!name) {
            log_debug("Failed to parse name at position %zu.", current - dict_start);
            break;
        }

        // Handle special cases for linearized PDFs, launch actions, JavaScript references
        if (strcmp(name, "Linearized") == 0) {
            obj->flags.linearized = 1;
            log_debug("Detected linearized PDF.");
        } else if (strcmp(name, "Launch") == 0) {
            obj->flags.has_launch_action = 1;
            log_debug("Detected launch action.");
        } else if (strcmp(name, "JavaScript") == 0) {
            obj->flags.has_javascript = 1;
            log_debug("Detected JavaScript reference.");
        }

        // Check for the presence of filters
        if (strcmp(name, "Filter") == 0) {
            obj->flags.has_filter = 1;
            log_debug("Detected filter in dictionary.");
        }

        // Move to the next token
        current = find_next_token(pdf, current);
    }

    // Additional logic for updating object metadata or other processing
    update_object_metadata(pdf, obj);
}

void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    // Initialize necessary variables
    int dict_start = 0;
    int dict_end = 0;
    int obj_size = obj->size;

    if (obj_size <= 0) {
        pdf_debug(pdf, "Object has invalid or zero size.");
        return;
    }

    // Locate the start and end of the object's dictionary
    dict_start = find_dict_start(pdf, obj);
    if (dict_start < 0) {
        pdf_debug(pdf, "Failed to locate the start of the dictionary.");
        return;
    }

    dict_end = find_dict_end(pdf, obj, dict_start);
    if (dict_end < dict_start) {
        pdf_debug(pdf, "Failed to locate the end of the dictionary.");
        return;
    }

    // Process PDF names within the dictionary
    process_dict_names(pdf, obj, dict_start, dict_end);

    // Handle special cases for linearized PDFs
    if (is_linearized(pdf, obj)) {
        handle_linearized_case(pdf, obj);
    }

    // Handle launch actions
    if (has_launch_action(pdf, obj)) {
        handle_launch_action(pdf, obj);
    }

    // Handle JavaScript references
    if (has_js_reference(pdf, obj)) {
        handle_js_reference(pdf, obj);
    }

    // Check for filters and update the object's flags
    if (has_filter(pdf, obj)) {
        obj->flags |= PDF_OBJ_FLAG_FILTERED;
        pdf_debug(pdf, "Object contains a filter.");
    } else {
        pdf_debug(pdf, "No filter detected in the object.");
    }

    pdf_debug(pdf, "Finished parsing PDF object.");
}

void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    int dict_start = 0, dict_end = 0;
    int obj_size = 0;

    if (!pdf || !obj) {
        return;
    }

    obj_size = obj->size;
    if (obj_size <= 0) {
        return;
    }

    dict_start = find_dict_start(pdf, obj);
    if (dict_start < 0) {
        return;
    }

    dict_end = find_dict_end(pdf, obj, dict_start);
    if (dict_end < 0) {
        return;
    }

    int name_pos = find_next_name(pdf, dict_start);
    while (name_pos >= dict_start && name_pos < dict_end) {
        char *name = extract_name(pdf, name_pos);
        if (strcmp(name, "Linearized") == 0) {
            obj->flags.linearized = 1;
        } else if (strcmp(name, "Launch") == 0) {
            obj->flags.launch_action = 1;
        } else if (strcmp(name, "JS") == 0) {
            obj->flags.java_script = 1;
        } else if (strcmp(name, "Filter") == 0) {
            obj->flags.has_filter = 1;
        }

        name_pos = find_next_name(pdf, name_pos + 1);
    }

    if (obj->flags.linearized) {
        log_debug("Linearized PDF detected.");
    }

    if (obj->flags.launch_action) {
        log_debug("Launch action detected.");
    }

    if (obj->flags.java_script) {
        log_debug("JavaScript reference detected.");
    }

    if (obj->flags.has_filter) {
        log_debug("Filter detected in object.");
    }
}
